def solve_stock_ledger(text):
    lines = text.split('\n')
    n = int(lines[0])
    stock = {}
    refused = 0
    for line in lines[1:1 + n]:
        op, item, k = line.split()
        k = int(k)
        have = stock.get(item, 0)
        if op == 'IN':
            stock[item] = have + k
        elif have >= k:
            stock[item] = have - k
        else:
            refused += 1
    out = [str(refused)]
    for item in sorted(stock):
        if stock[item] > 0:
            out.append(item + ' ' + str(stock[item]))
    return '\n'.join(out)
